1	/**
2	 * 城市浮生记 — 主入口
3	 *
4	 * 初始化游戏、管理渲染循环、绑定事件。
5	 */
6	
7	// ====== 全局游戏实例 ======
8	let gameStarted = false;
9	
10	
11	// ====== 工具函数 ======
12	
13	/** 设置属性条 */
14	function setStatBar(id, value, cssClass) {
15	  const wrap = document.getElementById(id);
16	  if (!wrap) return;
17	  const bar = wrap.querySelector(".stat-bar");
18	  const valEl = wrap.querySelector(".stat-value");
19	  if (bar) {
20	    bar.style.width = Math.max(0, Math.min(100, value)) + "%";
21	    bar.className = "stat-bar " + cssClass;
22	  }
23	  if (valEl) {
24	    valEl.textContent = Math.round(value);
25	  }
26	}
27	
28	/** 描述装备效果 */
29	function describeItemEffects(itemDef) {
30	  if (!itemDef || !itemDef.effects) return "";
31	  const parts = [];
32	  for (const [key, val] of Object.entries(itemDef.effects)) {
33	    if (key === "capacity") parts.push(`容量+${val}`);
34	    else if (key === "injury") parts.push(`受伤率${val < 0 ? val : "+" + val}`);
35	    else if (key === "illness")
36	      parts.push(`生病率${val < 0 ? val : "+" + val}`);
37	    else if (key === "fatigue") parts.push(`疲劳${val < 0 ? val : "+" + val}`);
38	    else if (typeof val === "number")
39	      parts.push(`${key}${val > 0 ? "+" + val : val}`);
40	  }
41	  return parts.join(", ");
42	}
43	
44	/** 检查工作需求是否满足 */
45	function checkJobRequirements(job, state) {
46	  const reqs = job.requirements || {};
47	  const p = state.player;
48	  const s = state.skills;
49	
50	  if (reqs.minAge && p.age < reqs.minAge) return `需要年满${reqs.minAge}岁`;
51	  if (reqs.maxAge && p.age > reqs.maxAge) return `年龄超过${reqs.maxAge}岁限制`;
52	  if (reqs.physique && p.physique < reqs.physique)
53	    return `体质不足 (需要${reqs.physique})`;
54	  if (reqs.intelligence && p.intelligence < reqs.intelligence)
55	    return `智力不足 (需要${reqs.intelligence})`;
56	  if (reqs.agility && p.agility < reqs.agility)
57	    return `敏捷不足 (需要${reqs.agility})`;
58	  if (reqs.mental && p.mental < reqs.mental)
59	    return `心智不足 (需要${reqs.mental})`;
60	  if (reqs.cooking && s.cooking.level < reqs.cooking)
61	    return `烹饪技能不足 (需要${reqs.cooking})`;
62	  if (reqs.repair && s.repair.level < reqs.repair)
63	    return `维修技能不足 (需要${reqs.repair})`;
64	  if (reqs.sales && s.sales.level < reqs.sales)
65	    return `销售技能不足 (需要${reqs.sales})`;
66	  if (reqs.english && s.english.level < reqs.english)
67	    return `英语技能不足 (需要${reqs.english})`;
68	
69	  return null; // 通过
70	}
71	
72	/** 估算工作收入 */
73	function estimateJobPay(job, state) {
74	  // 模拟3次取平均
75	  let total = 0;
76	  for (let i = 0; i < 10; i++) {
77	    total += job.payCalc(state);
78	  }
79	  return Math.floor(total / 10);
80	}
81	
82	// ====== 欢迎界面 ======
83	function showWelcome() {
84	  document.getElementById("app").style.display = "none";
85	  const welcome = document.getElementById("welcome-screen");
86	  welcome.style.display = "flex";
87	
88	  // 更新继续游戏按钮区域
89	  const loadSection = document.getElementById("load-section");
90	  if (loadSection) {
91	    const allSlots = getAllSlots();
92	    if (allSlots.length > 0) {
93	      // 找最新存档
94	      allSlots.sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0));
95	      const latest = allSlots[0];
96	      loadSection.style.display = "";
97	      loadSection.innerHTML = `
98	        <button id="btn-load-latest" class="btn btn-lg">📂 继续游戏 (第${latest.day}天, ¥${latest.cash?.toLocaleString() || 0})</button>
99	        <button id="btn-load-menu" class="btn btn-sm" style="margin-top:8px;">📋 选择存档...</button>
100	      `;
101	      document.getElementById("btn-load-latest").onclick = () =>
102	        loadExistingGame(latest.slot);
103	      document.getElementById("btn-load-menu").onclick = () =>
104	        showLoadMenuOnWelcome();
105	    } else {
106	      loadSection.style.display = "none";
107	    }
108	  }
109	
110	  document.getElementById("btn-new-game").onclick = () => startNewGame();
111	}
112	
113	function startNewGame() {
114	  StateManager.newGame();
115	  initializePrices();
116	  StateManager.addMessage(
117	    "🏘️ 你揣着2000元来到了这座城市。欠村长5500元，日息0.3%。活下去，活出个人样来！",
118	    "event",
119	  );
120	  StateManager.addMessage(
121	    '💡 提示：点击"🗺️ 地图"标签可查看城市全景。在城中村可以租房子、收废品。有了本钱可以去批发市场进货，再到商业区摆摊。',
122	    "info",
123	  );
124	  StateManager.addMessage(
125	    '🚶 点击行动页的"前往 XX"卡片或地图上的地点即可出行。左侧栏也有附近可前往的地点列表。',
126	    "info",
127	  );
128	  document.getElementById("welcome-screen").style.display = "none";
129	  document.getElementById("app").style.display = "";
130	  gameStarted = true;
131	  renderAll();
132	}
133	
134	function loadExistingGame(slot) {
135	  const saveData = loadGame(slot);
136	  if (saveData) {
137	    StateManager.importState(saveData);
138	    StateManager.addMessage("📂 存档已加载，欢迎回来！", "info");
139	    document.getElementById("welcome-screen").style.display = "none";
140	    document.getElementById("app").style.display = "";
141	    gameStarted = true;
142	    renderAll();
143	  }
144	}
