146	/** 欢迎界面上显示存档选择 */
147	function showLoadMenuOnWelcome() {
148	  const allSlots = getAllSlotsWithEmpty();
149	  let bodyHtml = '<div style="max-height:400px;overflow-y:auto;">';
150	  for (const s of allSlots) {
151	    if (s.empty) {
152	      bodyHtml += `<div style="padding:8px;margin:4px 0;background:var(--bg-card);border-radius:4px;opacity:0.4;font-size:12px;color:var(--text-muted);">${s.label} — 空</div>`;
153	    } else {
154	      const phaseLabel = s.phase === "corporate" ? "🏢" : "🏘️";
155	      bodyHtml += `
156	        <div style="padding:10px;margin:4px 0;background:var(--bg-card);border:1px solid var(--border);border-radius:4px;cursor:pointer;transition:all 0.2s;"
157	             onmouseover="this.style.borderColor='var(--accent)'" onmouseout="this.style.borderColor='var(--border)'"
158	             onclick="document.querySelector('.modal-overlay')?.remove();loadExistingGame('${s.slot}')">
159	          <div style="display:flex;justify-content:space-between;align-items:center;">
160	            <strong>${s.label}</strong>
161	            <span style="font-size:11px;color:var(--text-muted)">${s.date}</span>
162	          </div>
163	          <div style="font-size:12px;color:var(--text-secondary);margin-top:4px;">
164	            ${phaseLabel} 第${s.day}天 | 年龄${s.age} | 💰 ¥${s.cash?.toLocaleString() || 0}
165	            ${s.rank ? ` | 🏢 ${s.rank}` : ""}
166	            ${s.debt > 0 ? ` | ⚠️ 欠款 ¥${s.debt.toLocaleString()}` : ""}
167	          </div>
168	        </div>
169	      `;
170	    }
171	  }
172	  bodyHtml += "</div>";
173	
174	  showModal({
175	    title: "📂 读取存档",
176	    body: bodyHtml,
177	    buttons: [{ text: "取消", cls: "", callback: () => {} }],
178	  });
179	}
