181	/** 初始化各地商品价格 */
182	function initializePrices() {
183	  const state = StateManager.getState();
184	  for (const locKey of Object.keys(LOCATIONS)) {
185	    state.trade.goodsPrices[locKey] = {};
186	    const loc = LOCATIONS[locKey];
187	    for (const good of GOODS) {
188	      let price = good.basePrice;
189	      if (loc.priceMod && loc.priceMod[good.id]) {
190	        price *= loc.priceMod[good.id];
191	      }
192	      // 随机波动 ±10%
193	      price *= 0.9 + Math.random() * 0.2;
194	      price = Math.round(price * 100) / 100;
195	      state.trade.goodsPrices[locKey][good.id] = price;
196	    }
197	  }
198	  state.trade.lastPriceUpdate = state.player.day;
199	}
