201	// ====== 可用行动列表 ======
202	function getAvailableActions(state) {
203	  const actions = [];
204	
205	  // 提升为函数级变量（用 let，块内可重新指向用 const）
206	  const locKey = state.trade.currentLocation;
207	
208	  if (state.player.phase === "street") {
209	    // --- 街头阶段行动 ---
210	
211	    // 1. 工作
212	    const jobIds = getJobsAtLocation(locKey);
213	    for (const jobId of jobIds) {
214	      const job = getJobById(jobId);
215	      if (!job) continue;
216	      const reqFail = checkJobRequirements(job, state);
217	      const payEstimate = reqFail ? null : estimateJobPay(job, state);
218	
219	      actions.push({
220	        id: "job_" + jobId,
221	        name: job.name,
222	        desc: job.desc,
223	        icon: job.icon,
224	        payEstimate: payEstimate
225	          ? `${payEstimate - (job.startupCost || 0)}~${payEstimate + Math.floor(payEstimate * 0.3)}`
226	          : null,
227	        costEstimate: job.startupCost || null,
228	        reqFail,
229	        disabled:
230	          !!reqFail ||
231	          (job.startupCost && state.resources.cash < job.startupCost
232	            ? `启动资金不足(需¥${job.startupCost})`
233	            : null) ||
234	          null,
235	        handler: () => {
236	          const finalReq = checkJobRequirements(job, state);
237	          if (finalReq) {
238	            StateManager.addMessage(`⚠️ ${finalReq}`, "warning");
239	            return;
240	          }
241	          if (job.startupCost && state.resources.cash < job.startupCost) {
242	            StateManager.addMessage(
243	              `⚠️ 启动资金不足，需要 ¥${job.startupCost}`,
244	              "warning",
245	            );
246	            return;
247	          }
248	          doStreetJob(job);
249	        },
250	      });
251	    }
252	
253	    // 如果没有可用工作
254	    if (jobIds.length === 0) {
255	      actions.push({
256	        id: "no_jobs",
257	        name: "当前地点没有工作机会",
258	        desc: "尝试旅行到其他地点寻找工作。",
259	        icon: "🚫",
260	        disabled: true,
261	      });
262	    }
263	
264	    // 批发市场 — 批发进货
265	    if (locKey === "wholesaleMarket") {
266	      actions.push({
267	        id: "wholesale_header",
268	        name: "📦 批发进货（转到交易Tab）",
269	        desc: "在批发市场以折扣价批量购入商品，转手到商业区卖出赚差价！",
270	        icon: "📦",
271	        handler: () => {
272	          switchTab("trade");
273	        },
274	      });
275	    }
276	
277	    // 零售买卖 — 在任何有价格数据的地点都可以买卖
278	    if (
279	      state.trade.goodsPrices[locKey] &&
280	      Object.keys(state.trade.goodsPrices[locKey]).length > 0
281	    ) {
282	      actions.push({
283	        id: "trade_header",
284	        name: "🛒 买卖商品（转到交易Tab）",
285	        desc: "查看当前市场价格，低买高卖赚取差价。",
286	        icon: "🛒",
287	        handler: () => {
288	          switchTab("trade");
289	        },
290	      });
291	    }
292	
293	    // === 住所系统 ===
294	    if (locKey === "slum") {
295	      const currentTier = state.housing?.tier || 0;
296	      const HOUSING_TIERS = [
297	        {
298	          tier: 0,
299	          name: "露宿街头",
300	          cost: 0,
301	          rent: 0,
302	          capacity: 20,
303	          fatigueRecovery: 15,
304	          desc: "天为被，地为床。碰上刮风下雨就惨了。",
305	          icon: "🌃",
306	        },
307	        {
308	          tier: 1,
309	          name: "合租床位",
310	          cost: 300,
311	          rent: 12,
312	          capacity: 50,
313	          fatigueRecovery: 25,
314	          hygieneBonus: 5,
315	          desc: "城中村合租屋的一个床位，好歹有个遮风挡雨的地方。",
316	          icon: "🛏️",
317	        },
318	        {
319	          tier: 2,
320	          name: "单间",
321	          cost: 800,
322	          rent: 25,
323	          capacity: 100,
324	          fatigueRecovery: 35,
325	          hygieneBonus: 10,
326	          happinessBonus: 5,
327	          desc: "独立小单间，有床有柜子，私密多了。",
328	          icon: "🚪",
329	        },
330	        {
331	          tier: 3,
332	          name: "一居室",
333	          cost: 2000,
334	          rent: 50,
335	          capacity: 200,
336	          fatigueRecovery: 50,
337	          hygieneBonus: 15,
338	          happinessBonus: 10,
339	          desc: "正经的一室一厅，独立卫浴，生活质量质的飞跃。",
340	          icon: "🏠",
341	        },
342	      ];
343	
344	      // 显示当前住所
345	      const curHouse = HOUSING_TIERS[currentTier];
346	      actions.push({
347	        id: "housing_current",
348	        name: `${curHouse.icon} 当前住所：${curHouse.name}`,
349	        desc: `容量+${curHouse.capacity} | 睡眠恢复疲劳-${curHouse.fatigueRecovery} | ${curHouse.desc}${curHouse.rent > 0 ? ` | 日租¥${curHouse.rent}/天` : ""}`,
350	        icon: curHouse.icon,
351	        disabled: true,
352	      });
353	
354	      // 可升级的住所
355	      for (let t = currentTier + 1; t < HOUSING_TIERS.length; t++) {
356	        const house = HOUSING_TIERS[t];
357	        const canAfford = state.resources.cash >= house.cost;
358	        actions.push({
359	          id: "housing_upgrade_" + t,
360	          name: `⬆️ 升级到${house.name}`,
361	          desc: `${house.desc} 一次性付¥${house.cost} + 日租¥${house.rent}/天`,
362	          icon: house.icon,
363	          costEstimate: house.cost,
364	          disabled: !canAfford,
365	          reqFail: !canAfford ? `需 ¥${house.cost}` : null,
366	          handler: () => {
367	            state.resources.cash -= house.cost;
368	            state.housing.tier = t;
369	            state.housing.rentedDay = state.player.day;
370	            state.inventory.capacity =
371	              house.capacity + (state.housing.storageCapacity || 0);
372	            StateManager.addMessage(
373	              `🏠 搬进了${house.name}！容量提升至${state.inventory.capacity}。`,
374	              "success",
375	            );
376	          },
377	        });
378	      }
379	    }
380	
381	    // === 仓库租赁（批发市场）===
382	    if (locKey === "wholesaleMarket") {
383	      const hasStorage = state.housing?.storageRented;
384	      const STORAGE_OPTIONS = [
385	        {
386	          id: "small",
387	          name: "小仓库",
388	          cost: 500,
389	          rent: 20,
390	          capacity: 150,
391	          icon: "📦",
392	        },
393	        {
394	          id: "big",
395	          name: "大仓库",
396	          cost: 1500,
397	          rent: 50,
398	          capacity: 500,
399	          icon: "🏗️",
400	        },
401	      ];
402	
403	      if (hasStorage) {
404	        actions.push({
405	          id: "storage_current",
406	          name: `📦 已租仓库 (额外+${state.housing.storageCapacity || 0}容量)`,
407	          desc: `日租¥${STORAGE_OPTIONS.find((s) => s.capacity === state.housing.storageCapacity)?.rent || "?"}/天`,
408	          icon: "📦",
409	          disabled: true,
410	        });
411	      } else {
412	        for (const opt of STORAGE_OPTIONS) {
413	          const canAfford = state.resources.cash >= opt.cost;
414	          actions.push({
415	            id: "storage_rent_" + opt.id,
416	            name: `📦 租用${opt.name}`,
417	            desc: `额外+${opt.capacity}商品存储容量。一次性¥${opt.cost} + 日租¥${opt.rent}/天`,
418	            icon: opt.icon,
419	            costEstimate: opt.cost,
420	            disabled: !canAfford,
421	            reqFail: !canAfford ? `需 ¥${opt.cost}` : null,
422	            handler: () => {
423	              state.resources.cash -= opt.cost;
424	              state.housing.storageRented = true;
425	              state.housing.storageCapacity = opt.capacity;
426	              const baseCap = [20, 50, 100, 200][state.housing.tier || 0];
427	              state.inventory.capacity = baseCap + opt.capacity;
428	              StateManager.addMessage(
429	                `📦 租下了${opt.name}！总容量提升至${state.inventory.capacity}。`,
430	                "success",
431	              );
432	            },
433	          });
434	        }
435	      }
436	    }
437	
438	    // === 背包升级（商业区）===
439	    if (locKey === "commercialDist") {
440	      const BACKPACKS = [
441	        {
442	          id: "backpack_basic",
443	          name: "帆布背包",
444	          cost: 50,
445	          capacity: 5,
446	          icon: "🎒",
447	        },
448	        {
449	          id: "backpack_large",
450	          name: "大号旅行包",
451	          cost: 150,
452	          capacity: 15,
453	          icon: "🎒",
454	        },
455	        {
456	          id: "backpack_pro",
457	          name: "专业登山包",
458	          cost: 400,
459	          capacity: 30,
460	          icon: "🎒",
461	        },
462	      ];
463	      // 只显示未购买的
464	      const ownedPacks = state.inventory.items.filter((i) =>
465	        i.id.startsWith("backpack_"),
466	      );
467	      for (const pack of BACKPACKS) {
468	        if (ownedPacks.find((p) => p.id === pack.id)) continue;
469	        const canAfford = state.resources.cash >= pack.cost;
470	        actions.push({
471	          id: "buy_" + pack.id,
472	          name: `🛍️ 购买${pack.name}`,
473	          desc: `随身容量+${pack.capacity}。一次性购买，永久拥有。`,
474	          icon: pack.icon,
475	          costEstimate: pack.cost,
476	          disabled: !canAfford,
477	          handler: () => {
478	            state.resources.cash -= pack.cost;
479	            state.inventory.items.push({ id: pack.id, qty: 1 });
480	            state.inventory.capacity += pack.capacity;
481	            StateManager.addMessage(
482	              `🎒 购买了${pack.name}，随身容量+${pack.capacity}！`,
483	              "success",
484	            );
485	          },
486	        });
487	      }
488	    }
489	
490	    // 2. 旅行
491	    const reachable = getReachableLocations(locKey);
492	    for (const destKey of reachable) {
493	      const dest = getLocation(destKey);
494	      if (!dest) continue;
495	      actions.push({
496	        id: "travel_" + destKey,
497	        name: `前往 ${dest.name}`,
498	        desc: dest.desc,
499	        icon: "🚶",
500	        handler: () => {
501	          StateManager.update("trade.currentLocation", destKey);
502	          StateManager.addMessage(`🚶 你来到了${dest.name}。`, "info");
503	        },
504	      });
505	    }
506	
507	    // 3. 通用行动
508	    actions.push({
509	      id: "rest",
510	      name: "休息一会",
511	      desc: "找个地方坐坐，恢复一些疲劳。",
512	      icon: "😴",
513	      handler: () => {
514	        const state = StateManager.getState();
515	        const recovery = 25 + Math.floor(Math.random() * 15);
516	        state.needs.fatigue = Math.max(0, state.needs.fatigue - recovery);
517	        state.needs.happiness = Math.min(100, state.needs.happiness + 5);
518	        StateManager.addMessage(`😴 你休息了一会，疲劳-${recovery}。`, "info");
519	      },
520	    });
521	
522	    actions.push({
523	      id: "eat",
524	      name: "吃顿饭",
525	      desc: "花10元在路边摊吃个快餐，填饱肚子。",
526	      icon: "🍚",
527	      costEstimate: 10,
528	      disabled: state.resources.cash < 10 ? true : false,
529	      handler: () => {
530	        const st = StateManager.getState();
531	        if (st.resources.cash < 10) {
532	          StateManager.addMessage("⚠️ 钱不够吃饭了！", "danger");
533	          return;
534	        }
535	        st.resources.cash -= 10;
536	        st.needs.hunger = Math.min(100, st.needs.hunger + 35);
537	        st.needs.happiness = Math.min(100, st.needs.happiness + 8);
538	        StateManager.addMessage(
539	          "🍚 你花10元吃了顿饭，肚子饱了心情好了。",
540	          "success",
541	        );
542	      },
543	    });
544	
545	    actions.push({
546	      id: "shower",
547	      name: "洗澡",
548	      desc: "花5元去公共澡堂洗个澡。",
