991	function addSkillXp(skillKey, amount) {
992	  if (!amount || amount <= 0) return;
993	  const state = StateManager.getState();
994	  const skill = state.skills[skillKey];
995	  if (!skill) return;
996	  skill.xp += amount;
997	  const xpNeeded = (skill.level + 1) * 100;
998	  if (skill.xp >= xpNeeded && skill.level < 100) {
999	    skill.level++;
1000	    skill.xp -= xpNeeded;
1001	    StateManager.addMessage(
1002	      `⭐ ${getSkillName(skillKey)}升级到 Lv.${skill.level}！`,
1003	      "success",
1004	    );
1005	  }
1006	}
