743	 * 二、事件触发与队列管理
744	 * ========================================================= */
745	
746	/** 街头每日事件判定 */
747	function rollStreetEvent(state) {
748	  // 基础 18% 触发率，已存在待弹事件时不重复触发
749	  if (state._pendingEvent) return;
750	  const baseChance = 0.18;
751	  // 健康差或债务高时提高触发率
752	  let mod = 0;
753	  if (state.status.health < 50) mod += 0.1;
754	  if (state.resources.debt > 3000) mod += 0.05;
755	  if (state.needs.happiness < 30) mod += 0.05;
756	  if (Math.random() < baseChance + mod) {
757	    queueRandomEvent(state, "street");
758	  }
759	}
760	
761	/** 职场每日事件判定 */
762	function rollCorporateEvent(state) {
763	  if (state._pendingEvent) return;
764	  const baseChance = 0.22;
765	  let mod = 0;
766	  if (state.player.corporate.risk > 50) mod += 0.1;
767	  if (state.player.corporate.popularity < 30) mod += 0.05;
768	  if (state.player.corporate.upwardMgmt < 20) mod += 0.05;
769	  if (Math.random() < baseChance + mod) {
770	    queueRandomEvent(state, "corporate");
771	  }
772	}
773	
774	/** 把一个随机事件塞进待弹队列 */
775	function queueRandomEvent(state, phase) {
776	  const pool = RANDOM_EVENTS.filter((e) => e.phase === phase);
777	  if (pool.length === 0) return;
778	
779	  // 过滤掉不满足条件的事件
780	  const eligible = pool.filter((e) => !e.conditions || e.conditions(state));
781	  if (eligible.length === 0) return;
782	
783	  const evt = eligible[Math.floor(Math.random() * eligible.length)];
784	  state._pendingEvent = evt;
785	  // 触发延迟到 render 阶段弹（避免在 tick 内部阻塞）
786	  setTimeout(() => {
787	    if (StateManager.getState()._pendingEvent === evt) {
788	      showEventModal(evt);
789	    }
790	  }, 50);
791	}
