794	 * 三、事件弹窗 UI
795	 * ========================================================= */
796	
797	/**
798	 * 渲染并展示一个事件模态框
799	 * @param {Object} evt - 事件对象
800	 */
801	function showEventModal(evt) {
802	  // 先卸掉任何旧弹窗
803	  document.querySelector(".modal-overlay")?.remove();
804	
805	  // 构建选项HTML
806	  const choicesHtml = evt.choices
807	    .map((ch, i) => {
808	      const hintStr = ch.hint
809	        ? `<div class="choice-hint">${ch.hint}</div>`
810	        : "";
811	      // 检查现金是否够
812	      let disabled = false;
813	      if (ch.cost && StateManager.getState().resources.cash < ch.cost) {
814	        disabled = true;
815	      }
816	      const costTag = ch.cost
817	        ? ` <span style="color:var(--warning);font-size:11px;">需 ¥${ch.cost}</span>`
818	        : "";
819	      return `
820	        <button class="event-choice ${disabled ? "disabled" : ""}" data-idx="${i}" ${disabled ? "disabled" : ""}>
821	          <div class="choice-main">${ch.text}${costTag}</div>
822	          ${hintStr}
823	        </button>
824	      `;
825	    })
826	    .join("");
827	
828	  const overlay = document.createElement("div");
829	  overlay.className = "modal-overlay event-modal";
830	  overlay.innerHTML = `
831	    <div class="modal-box event-box">
832	      <div class="event-header">
833	        <div class="event-icon">${evt.icon}</div>
834	        <h2 class="event-title">${evt.title}</h2>
835	      </div>
836	      <p class="event-story">${evt.story}</p>
837	      <div class="event-choices">${choicesHtml}</div>
838	      <div style="text-align:center;margin-top:8px;font-size:10px;color:var(--text-muted);">
839	        ⏰ 这是一个会影响数值的选择，请谨慎决定
840	      </div>
841	    </div>
842	  `;
843	  document.body.appendChild(overlay);
844	
845	  // 绑定选项点击
846	  overlay.querySelectorAll(".event-choice").forEach((btn) => {
847	    btn.addEventListener("click", () => {
848	      const idx = parseInt(btn.dataset.idx);
849	      const choice = evt.choices[idx];
850	      if (!choice) return;
851	      const state = StateManager.getState();
852	      try {
853	        if (typeof choice.apply === "function") {
854	          choice.apply(state);
855	        }
856	      } catch (e) {
857	        console.error("Event choice apply error:", e);
858	      }
859	      // 清掉待弹事件
860	      state._pendingEvent = null;
861	      // 关闭弹窗 + 重新渲染
862	      document.body.removeChild(overlay);
863	      renderAll();
864	    });
865	  });
866	}
867	
868	/** 跳槽 offer 决策弹窗（被 corp_headhunter 事件调用） */
869	function showJobOfferModal() {
870	  const state = StateManager.getState();
871	  const offer = state.corporate.jobOffer;
872	  if (!offer) return;
873	  showModal({
874	    title: "💼 跳槽 Offer 决策",
875	    body: `
876	      <p>另一家公司开出了 <strong style="color:var(--success);">年薪 ¥${offer.salary.toLocaleString()}</strong> 的条件挖你！</p>
877	      <p style="font-size:12px;color:var(--text-secondary);">跳槽有风险：人缘归零、向上管理归零、KPI 减半、需重新建立关系。</p>
878	    `,
879	    buttons: [
880	      { text: "继续考虑", cls: "", callback: () => {} },
881	      {
882	        text: `接受 Offer (¥${offer.salary.toLocaleString()})`,
883	        cls: "btn-success",
884	        callback: () => {
885	          // 简化版：直接加钱 + 重置属性
886	          state.resources.cash += offer.salary;
887	          state.player.corporate.kpi = Math.max(
888	            0,
889	            state.player.corporate.kpi * 0.5,
890	          );
891	          state.player.corporate.popularity = Math.max(
892	            0,
893	            state.player.corporate.popularity - 30,
894	          );
895	          state.player.corporate.upwardMgmt = Math.max(
896	            0,
897	            state.player.corporate.upwardMgmt - 30,
898	          );
899	          state.corporate.jobOffer = null;
900	          StateManager.addMessage(
901	            `💼 接受了新公司的 offer，拿到 ¥${offer.salary.toLocaleString()} 签字费！`,
902	            "event",
903	          );
904	          renderAll();
905	        },
906	      },
907	    ],
908	  });
909	}
910	
911	/* =========================================================
912	 * 四、兼容旧 API
913	 * ========================================================= */
914	
915	/** 每日新闻判定（旧 API，保持兼容） */
916	function rollDailyNews(state) {
917	  // 街头阶段不再发广播新闻，改用事件弹窗
918	  if (state.player.phase === "street") {
919	    rollStreetEvent(state);
920	    return;
921	  }
922	  // 职场阶段：保留少量市场新闻 + 事件弹窗
923	  const newsChance = state.activeNews.length > 0 ? 0.05 : 0.12;
924	  if (Math.random() < newsChance) {
925	    const news = getRandomNewsEvent();
926	    if (news && !state.flags.seenNewsToday.includes(news.id)) {
927	      news._appliedDay = state.player.day;
928	      state.activeNews.push(news);
929	      state.flags.seenNewsToday.push(news.id);
930	      applyNewsEffect(news, state);
931	      StateManager.addMessage(`📰 ${news.headline}`, "event");
932	    }
933	  }
934	  // 职场事件
935	  rollCorporateEvent(state);
936	  // 清理今日已见新闻列表
937	  if (state.player.day % 3 === 0) {
938	    state.flags.seenNewsToday = [];
939	  }
940	}
