541	        st.resources.cash += earned;
542	        st.resources.totalEarned += earned;
543	        st.skills.sales.xp += 20;
544	        st.status.fame = Math.min(100, st.status.fame + 2);
545	        StateManager.addMessage(
546	          `🏪 摆摊大成功！赚 ¥${earned}！销售经验++`,
547	          "success",
548	        );
549	      } else if (luck < 0.85) {
550	        // 小赚
551	        const earned = 50 + Math.floor(Math.random() * 150);
552	        st.resources.cash += earned;
553	        st.resources.totalEarned += earned;
554	        st.skills.sales.xp += 10;
555	        StateManager.addMessage(`🏪 摆摊小赚 ¥${earned}。`, "success");
556	      } else {
557	        // 亏了
