617	function showYuEBaoModal() {
618	  const state = StateManager.getState();
619	  const yue = state.flags.yuEBao || 0;
620	  const todayInterest = Math.floor(yue * 0.0001);
621	  showModal({
622	    title: "💰 余额宝理财",
623	    body: `
624	      <p>当前余额宝: <strong style="color:var(--success);">¥${yue.toLocaleString()}</strong></p>
625	      <p>今日收益预估: <strong>+¥${todayInterest}</strong>（日息 0.01%）</p>
