147	    ],
148	  },
149	];
150	
151	/* =========================================================
152	 * 一、初始化 & 行情更新
153	 * ========================================================= */
154	
155	/** 初始化股市 */
156	function initStockMarket(state) {
157	  for (const stock of STOCK_LIST) {
158	    state.corporate.stockMarket[stock.symbol] = {
159	      price: stock.basePrice * (0.85 + Math.random() * 0.3),
160	      history: [], // [{ day, price }]
161	      high20: stock.basePrice,
162	      low20: stock.basePrice,
163	      lastNewsDay: -999,
164	      _initialized: false,
165	    };
166	  }
167	}
168	
169	/** 初始化时填入少量历史走势 */
170	function bootstrapStockHistory(state) {
171	  for (const sym of Object.keys(state.corporate.stockMarket)) {
172	    const market = state.corporate.stockMarket[sym];
173	    const def = STOCK_LIST.find((s) => s.symbol === sym);
174	    if (!def) continue;
175	    if (!market._initialized) {
176	      market._initialized = true;
177	      // 倒推 20 天历史
178	      let p = market.price / (0.85 + Math.random() * 0.3);
179	      for (let i = 0; i < 20; i++) {
180	        const change = 1 + (Math.random() - 0.5) * def.volatility;
181	        p = p * change;
182	        market.history.push({ day: state.player.day - (20 - i), price: p });
183	      }
184	      market.history.push({ day: state.player.day, price: market.price });
185	      market.high20 = Math.max(...market.history.map((h) => h.price));
186	      market.low20 = Math.min(...market.history.map((h) => h.price));
187	    }
188	  }
189	}
190	
191	/** 更新股市价格（每日 / 季末） */
192	function updateStockPrices(state, forceNews = false) {
193	  for (const stock of STOCK_LIST) {
194	    const market = state.corporate.stockMarket[stock.symbol];
195	    if (!market) continue;
196	
197	    // 1) 基础趋势（每日漂移）
198	    const trend = stock.baseTrend;
199	    // 2) 随机扰动（正态分布近似）
200	    const noise = (Math.random() - 0.5) * 2 * stock.volatility;
201	    // 3) 均值回归（偏离20日均价过远时拉回一些）
202	    let meanReversion = 0;
203	    if (market.history.length >= 5) {
204	      const recent = market.history.slice(-5);
205	      const avg = recent.reduce((s, h) => s + h.price, 0) / recent.length;
206	      meanReversion = ((avg - market.price) / avg) * 0.15;
207	    }
208	    const change = 1 + trend + noise + meanReversion;
209	    market.price = Math.max(0.5, market.price * change);
210	    market.price = Math.round(market.price * 100) / 100;
211	
212	    // 4) 新闻冲击（5% 概率触发）
213	    if (forceNews || Math.random() < 0.05) {
214	      const newsPool = STOCK_NEWS_TEMPLATES.find(
215	        (n) => n.symbol === stock.symbol,
216	      );
217	      if (newsPool && state.player.day - market.lastNewsDay > 3) {
218	        const news =
219	          newsPool.headlines[
220	            Math.floor(Math.random() * newsPool.headlines.length)
221	          ];
222	        market.price = Math.max(0.5, market.price * (1 + news.impact));
223	        market.price = Math.round(market.price * 100) / 100;
224	        market.lastNewsDay = state.player.day;
225	        StateManager.addMessage(
226	          `📊 [${stock.symbol}] ${news.text}`,
227	          news.impact > 0 ? "success" : "danger",
228	        );
229	      }
230	    }
231	
232	    // 记录历史
233	    market.history.push({ day: state.player.day, price: market.price });
234	    if (market.history.length > 20) market.history.shift();
235	    market.high20 = Math.max(...market.history.map((h) => h.price));
236	    market.low20 = Math.min(...market.history.map((h) => h.price));
237	  }
238	}
239	
240	/* =========================================================
241	 * 二、买卖接口
242	 * ========================================================= */
243	
244	/** 买入股票 */
245	function buyStock(symbol, shares) {
246	  const state = StateManager.getState();
247	  const market = state.corporate.stockMarket[symbol];
248	  if (!market) {
249	    StateManager.addMessage("⚠️ 不存在的股票。", "danger");
250	    return false;
251	  }
252	
253	  shares = Math.floor(shares);
254	  if (shares <= 0) {
255	    StateManager.addMessage("⚠️ 至少买入1股。", "warning");
256	    return false;
257	  }
258	
259	  const cost = Math.round(market.price * shares * 100) / 100;
260	  if (state.resources.cash < cost) {
261	    StateManager.addMessage(
262	      `⚠️ 需要 ¥${cost.toLocaleString()}，现金不足。`,
263	      "danger",
264	    );
265	    return false;
266	  }
267	
268	  state.resources.cash -= cost;
269	
270	  const existing = state.corporate.stocks.find((s) => s.symbol === symbol);
271	  if (existing) {
272	    const totalShares = existing.shares + shares;
273	    existing.avgPrice =
274	      Math.round(
275	        ((existing.avgPrice * existing.shares + cost) / totalShares) * 100,
276	      ) / 100;
277	    existing.shares = totalShares;
278	  } else {
279	    state.corporate.stocks.push({
280	      symbol,
281	      name: STOCK_LIST.find((s) => s.symbol === symbol)?.name || symbol,
282	      shares,
283	      avgPrice: market.price,
284	    });
285	  }
286	
287	  StateManager.addMessage(
288	    `📈 买入 ${symbol} ×${shares}股 @¥${market.price}，共 ¥${cost.toLocaleString()}`,
289	    "success",
290	  );
291	  return true;
292	}
293	
294	/** 卖出股票 */
295	function sellStock(symbol, shares) {
296	  const state = StateManager.getState();
297	  const holding = state.corporate.stocks.find((s) => s.symbol === symbol);
298	  if (!holding || holding.shares < shares) {
299	    StateManager.addMessage("⚠️ 持仓不足。", "danger");
300	    return false;
301	  }
302	
303	  const market = state.corporate.stockMarket[symbol];
304	  const revenue = Math.round(market.price * shares * 100) / 100;
305	  const profit = revenue - holding.avgPrice * shares;
306	
307	  state.resources.cash += revenue;
308	  state.resources.totalEarned += Math.max(0, profit);
309	
310	  holding.shares -= shares;
311	  if (holding.shares <= 0) {
312	    state.corporate.stocks = state.corporate.stocks.filter(
313	      (s) => s.symbol !== symbol,
314	    );
315	  }
316	
317	  const profitStr =
318	    profit >= 0
319	      ? `📈 盈利 ¥${Math.round(profit).toLocaleString()}`
320	      : `📉 亏损 ¥${Math.abs(Math.round(profit)).toLocaleString()}`;
321	  StateManager.addMessage(
322	    `💰 卖出 ${symbol} ×${shares}股，¥${revenue.toLocaleString()}。${profitStr}`,
323	    profit >= 0 ? "success" : "warning",
324	  );
325	  return true;
326	}
327	
328	/** 计算能全部买入的股数（按当前价） */
329	function calcMaxBuyShares(symbol) {
330	  const state = StateManager.getState();
331	  const market = state.corporate.stockMarket[symbol];
332	  if (!market || market.price <= 0) return 0;
333	  // 保留 1 元，避免精度问题
334	  const cash = Math.max(0, state.resources.cash - 1);
335	  return Math.floor(cash / market.price);
336	}
337	
338	/* =========================================================
339	 * 三、交易 UI
340	 * ========================================================= */
341	
342	/** 渲染简易 K 线（折线图 + 颜色块） */
343	function renderKLine(history, currentPrice) {
344	  if (!history || history.length < 2) {
345	    return '<div style="color:var(--text-muted);font-size:10px;">无历史数据</div>';
346	  }
347	  const prices = history.map((h) => h.price);
348	  const max = Math.max(...prices, currentPrice);
349	  const min = Math.min(...prices, currentPrice);
350	  const range = max - min || 1;
351	  const w = 140; // svg width
352	  const h = 40; // svg height
353	  const stepX = w / (history.length - 1);
354	  const points = history
355	    .map((p, i) => {
356	      const x = i * stepX;
357	      const y = h - ((p.price - min) / range) * h;
358	      return `${x.toFixed(1)},${y.toFixed(1)}`;
359	    })
360	    .join(" ");
361	
362	  const firstPrice = history[0].price;
363	  const lastPrice = history[history.length - 1].price;
364	  const lineColor =
365	    lastPrice >= firstPrice ? "var(--success)" : "var(--danger)";
366	  const fillColor =
367	    lastPrice >= firstPrice ? "rgba(46,204,113,0.12)" : "rgba(231,76,60,0.12)";
368	
369	  // 构造一个 polygon 用于填充
370	  const fillPoints = `0,${h} ${points} ${w},${h}`;
371	
372	  return `
373	    <svg width="${w}" height="${h}" style="display:block;margin-top:4px;">
374	      <polygon points="${fillPoints}" fill="${fillColor}" />
375	      <polyline points="${points}" fill="none" stroke="${lineColor}" stroke-width="1.5" />
376	    </svg>
377	  `;
378	}
379	
380	/** 渲染单只股票卡片 */
381	function renderStockCard(stock, state) {
382	  const market = state.corporate.stockMarket[stock.symbol];
383	  if (!market) return "";
384	  const price = market.price;
385	  const holding = state.corporate.stocks.find((s) => s.symbol === stock.symbol);
386	  const shares = holding ? holding.shares : 0;
387	
388	  // 今日涨跌（vs 上一日）
389	  const prev =
390	    market.history.length >= 2
391	      ? market.history[market.history.length - 2].price
392	      : price;
393	  const todayChange = price - prev;
394	  const todayPct = (todayChange / prev) * 100;
395	
396	  // 7日均价
397	  const last7 = market.history.slice(-7);
398	  const avg7 =
399	    last7.length > 0
400	      ? last7.reduce((s, h) => s + h.price, 0) / last7.length
401	      : price;
402	  const aboveAvg7 = price > avg7;
403	
404	  // 持仓盈亏
405	  const pnl = holding ? Math.round((price - holding.avgPrice) * shares) : 0;
406	  const pnlPct = holding
407	    ? ((price - holding.avgPrice) / holding.avgPrice) * 100
408	    : 0;
409	  const pnlColor = pnl >= 0 ? "var(--success)" : "var(--danger)";
410	  const trendColor = todayChange >= 0 ? "var(--success)" : "var(--danger)";
411	  const trendIcon = todayChange >= 0 ? "▲" : "▼";
412	
413	  // 全买/全卖能买多少
414	  const maxBuy = calcMaxBuyShares(stock.symbol);
415	  const maxSell = shares;
416	
417	  return `
418	    <div class="action-card stock-card" style="border-left:3px solid ${trendColor};">
419	      <div style="display:flex;justify-content:space-between;align-items:flex-start;">
420	        <div>
421	          <div class="card-title" style="margin:0;">${stock.symbol} ${stock.name}</div>
422	          <div style="font-size:10px;color:var(--text-muted);">${stock.industry} | 波动率${(stock.volatility * 100).toFixed(0)}%</div>
423	        </div>
424	        <div style="text-align:right;">
425	          <div style="font-size:18px;font-weight:700;color:${trendColor};">¥${price.toFixed(2)}</div>
426	          <div style="font-size:11px;color:${trendColor};">${trendIcon} ${todayChange >= 0 ? "+" : ""}${todayChange.toFixed(2)} (${todayPct >= 0 ? "+" : ""}${todayPct.toFixed(2)}%)</div>
427	        </div>
428	      </div>
429	
430	      <div style="display:flex;justify-content:space-between;align-items:center;margin:4px 0;font-size:10px;color:var(--text-muted);">
431	        <span>7日均 ¥${avg7.toFixed(2)} ${aboveAvg7 ? "🟢" : "🔴"}</span>
432	        <span>20日高 ¥${market.high20.toFixed(2)}</span>
433	        <span>20日低 ¥${market.low20.toFixed(2)}</span>
434	      </div>
435	
436	      ${renderKLine(market.history, price)}
437	
438	      ${
439	        shares > 0
440	          ? `
441	        <div style="margin-top:8px;padding:6px 8px;background:rgba(0,180,216,0.06);border-radius:4px;font-size:11px;">
442	          <div style="display:flex;justify-content:space-between;">
443	            <span>持仓: <strong>${shares}</strong>股 | 均价 <strong>¥${holding.avgPrice.toFixed(2)}</strong></span>
444	            <span style="color:${pnlColor};font-weight:600;">${pnl >= 0 ? "+" : ""}¥${pnl.toLocaleString()} (${pnlPct >= 0 ? "+" : ""}${pnlPct.toFixed(1)}%)</span>
445	          </div>
446	        </div>
447	      `
448	          : ""
449	      }
450	
451	      <div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:8px;">
452	        <button class="btn btn-sm btn-success stock-buy" data-sym="${stock.symbol}" data-qty="10">买10</button>
453	        <button class="btn btn-sm btn-success stock-buy" data-sym="${stock.symbol}" data-qty="100">买100</button>
454	        <button class="btn btn-sm btn-primary stock-buy-all" data-sym="${stock.symbol}" ${maxBuy === 0 ? "disabled" : ""} title="用所有现金按当前价买入">📦 全部买入 (${maxBuy})</button>
455	        <button class="btn btn-sm btn-danger stock-sell" data-sym="${stock.symbol}" data-qty="10" ${shares === 0 ? "disabled" : ""}>卖10</button>
456	        <button class="btn btn-sm btn-danger stock-sell-all" data-sym="${stock.symbol}" ${shares === 0 ? "disabled" : ""} title="卖出全部持仓">💰 全部卖出 (${shares})</button>
457	      </div>
458	    </div>
459	  `;
460	}
461	
462	function showStockTradeModal() {
463	  const state = StateManager.getState();
464	  // 首次打开：bootstrap 历史
465	  if (Object.values(state.corporate.stockMarket).some((m) => !m._initialized)) {
466	    bootstrapStockHistory(state);
467	  }
468	
469	  // 持仓概览
470	  const totalStockValue = state.corporate.stocks.reduce((sum, s) => {
471	    const m = state.corporate.stockMarket[s.symbol];
472	    return sum + (m ? m.price * s.shares : 0);
473	  }, 0);
474	  const totalCost = state.corporate.stocks.reduce(
475	    (sum, s) => sum + s.avgPrice * s.shares,
476	    0,
477	  );
478	  const totalPnL = Math.round(totalStockValue - totalCost);
479	  const pnlColor = totalPnL >= 0 ? "var(--success)" : "var(--danger)";
480	
481	  let body = `
482	    <div style="display:flex;justify-content:space-between;align-items:center;padding:10px 12px;background:var(--bg-card);border-radius:6px;margin-bottom:12px;">
483	      <div>
484	        <div style="font-size:11px;color:var(--text-muted);">现金</div>
485	        <div style="font-size:16px;font-weight:600;color:var(--success);">¥${state.resources.cash.toLocaleString()}</div>
486	      </div>
487	      <div>
488	        <div style="font-size:11px;color:var(--text-muted);">持仓市值</div>
489	        <div style="font-size:16px;font-weight:600;">¥${totalStockValue.toLocaleString()}</div>
490	      </div>
491	      <div>
492	        <div style="font-size:11px;color:var(--text-muted);">浮动盈亏</div>
493	        <div style="font-size:16px;font-weight:600;color:${pnlColor};">${totalPnL >= 0 ? "+" : ""}¥${totalPnL.toLocaleString()}</div>
494	      </div>
495	    </div>
496	    <p style="font-size:11px;color:var(--text-muted);margin-bottom:8px;">
497	      💡 提示：每只股票有独立的行业、波动率，会受公司新闻影响。价格每日波动 + 漂移 + 回归。
498	    </p>
499	    <div style="max-height:55vh;overflow-y:auto;display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:8px;">
500	  `;
501	
502	  for (const stock of STOCK_LIST) {
503	    body += renderStockCard(stock, state);
504	  }
505	  body += "</div>";
506	
507	  showModal({
508	    title: "📈 股票交易 (8只多行业)",
509	    body,
510	    buttons: [
511	      {
512	        text: "🚀 刷新行情",
513	        cls: "btn-primary",
514	        callback: () => {
515	          // 模拟一次价格更新看看效果
516	          updateStockPrices(state, false);
517	          showStockTradeModal();
518	        },
519	      },
520	      {
521	        text: "关闭",
522	        cls: "",
523	        callback: () => {
524	          renderAll();
525	        },
526	      },
527	    ],
528	  });
529	
530	  // 绑定按钮
531	  setTimeout(() => {
532	    document.querySelectorAll(".stock-buy").forEach((btn) => {
533	      btn.onclick = () => {
534	        buyStock(btn.dataset.sym, parseInt(btn.dataset.qty));
535	        showStockTradeModal();
536	      };
537	    });
538	    document.querySelectorAll(".stock-buy-all").forEach((btn) => {
539	      btn.onclick = () => {
540	        const sym = btn.dataset.sym;
541	        const qty = calcMaxBuyShares(sym);
542	        if (qty > 0) {
543	          buyStock(sym, qty);
544	        } else {
545	          StateManager.addMessage("⚠️ 现金不足买入 1 股。", "warning");
546	        }
547	        showStockTradeModal();
548	      };
549	    });
550	    document.querySelectorAll(".stock-sell").forEach((btn) => {
551	      btn.onclick = () => {
552	        const sym = btn.dataset.sym;
553	        const qty = parseInt(btn.dataset.qty);
554	        const holding = state.corporate.stocks.find((s) => s.symbol === sym);
555	        if (holding && holding.shares > 0) {
556	          sellStock(sym, Math.min(qty, holding.shares));
557	        }
558	        showStockTradeModal();
559	      };
560	    });
561	    document.querySelectorAll(".stock-sell-all").forEach((btn) => {
562	      btn.onclick = () => {
563	        const sym = btn.dataset.sym;
564	        const holding = state.corporate.stocks.find((s) => s.symbol === sym);
565	        if (holding && holding.shares > 0) {
566	          sellStock(sym, holding.shares);
567	        } else {
568	          StateManager.addMessage("⚠️ 没有持仓可卖。", "warning");
569	        }
570	        showStockTradeModal();
571	      };
572	    });
573	  }, 50);
574	}
575	
576	/** 刷新行情的辅助函数（季度切换时调用） */
577	function refreshStockMarket(state) {
578	  updateStockPrices(state, true);
579	  bootstrapStockHistory(state);
580	}
