/**
 * 股票交易系统（重做版）
 *
 * 改进点：
 * 1. 8 只股票，分行业（科技/金融/消费/医药/能源/房地产/工业/媒体）
 * 2. 每只股票有独立的"波动率"、"趋势"、"公司新闻"等参数
 * 3. 行情更新：基础趋势 + 随机扰动 + 新闻冲击
 * 4. 完整的 K 线图（最近 20 日走势）
 * 5. 「全部购入」「全部卖出」按钮
 * 6. 量化指标：今日涨跌 / 7 日均线 / 持仓盈亏 / 收益率
 */

const STOCK_LIST = [
  // === 高波动：科技 ===
  {
    symbol: "STAR",
    name: "星辰科技",
    industry: "科技",
    basePrice: 120,
    volatility: 0.18,
    baseTrend: 0.005,
    desc: "AI 概念龙头，成长性高但波动剧烈",
  },
  {
    symbol: "BYTE",
    name: "字节龙",
    industry: "科技",
    basePrice: 280,
    volatility: 0.16,
    baseTrend: 0.004,
    desc: "互联网巨头，护城河深",
  },
  {
    symbol: "GAME",
    name: "好玩游戏",
    industry: "科技",
    basePrice: 45,
    volatility: 0.22,
    baseTrend: -0.003,
    desc: "游戏股，受版号影响大",
  },
  // === 中波动：金融 / 消费 ===
  {
    symbol: "SAFE",
    name: "安信金融",
    industry: "金融",
    basePrice: 65,
    volatility: 0.08,
    baseTrend: 0.002,
    desc: "国有大行，稳健分红",
  },
  {
    symbol: "BREW",
    name: "醉鹅啤酒",
    industry: "消费",
    basePrice: 35,
    volatility: 0.07,
    baseTrend: 0.001,
    desc: "国民啤酒龙头，业绩稳定",
  },
  {
    symbol: "DRUG",
    name: "华佗医药",
    industry: "医药",
    basePrice: 95,
    volatility: 0.13,
    baseTrend: 0.003,
    desc: "创新药企，政策敏感",
  },
  // === 高波动：周期 / 题材 ===
  {
    symbol: "OIL",
    name: "黑金能源",
    industry: "能源",
    basePrice: 18,
    volatility: 0.15,
    baseTrend: 0.0,
    desc: "国际油价绑定，大起大落",
  },
  {
    symbol: "ESTATE",
    name: "万城地产",
    industry: "房地产",
    basePrice: 8.5,
    volatility: 0.2,
    baseTrend: -0.008,
    desc: "行业寒冬，股价一路阴跌",
  },
];

/** 公司新闻：随机触发，会大幅影响特定股票 */
const STOCK_NEWS_TEMPLATES = [
  {
    symbol: "STAR",
    headlines: [
