      hygiene: 75,
      happiness: 55,
    },

    // --- 派生状态 ---
    status: {
      health: 100,
      fame: 0,
      emotionalState: "stable", // stable|happy|sad|angry|stressed|depressed
      sick: false,
      injured: false,
    },

