function initInvestment(state) {
  const inv = state.investment;
  if (!inv) return;
  for (const s of INV_STOCKS) {
    if (!inv.stockMarket[s.symbol]) {
      inv.stockMarket[s.symbol] = { price: s.basePrice * (0.85 + Math.random() * 0.3), history: [], lastNewsDay: -999 };
    }
  }
  if (inv.btcPrice <= 0) inv.btcPrice = 200000;
  inv.lastTickDay = state.player.day;
}

function bootstrapInvestmentHistory(state) {
  const inv = state.investment;
  for (const sym of Object.keys(inv.stockMarket)) {
    const m = inv.stockMarket[sym];
    if (m.history.length === 0) {
      let p = m.price / (0.9 + Math.random() * 0.2);
      for (let i = 0; i < 20; i++) {
        p *= 0.98 + Math.random() * 0.04;
        m.history.push({ day: state.player.day - 20 + i, price: Math.round(p * 100) / 100 });
      }
    }
  }
}

// ====== 每日tick ======
function tickInvestmentDaily(state) {
  const inv = state.investment;
  if (!inv) return;
  if (inv.lastTickDay >= state.player.day) return;
  inv.lastTickDay = state.player.day;

  // 股票行情
  for (const s of INV_STOCKS) {
    const m = inv.stockMarket[s.symbol];
    if (!m) continue;
    const noise = (Math.random() - 0.5) * 2 * s.volatility;
    let reversion = 0;
    if (m.history.length >= 5) {
      const avg = m.history.slice(-5).reduce((a, h) => a + h.price, 0) / 5;
      reversion = ((avg - m.price) / avg) * 0.1;
    }
    m.price = Math.max(0.5, m.price * (1 + s.trend + noise + reversion));
    m.price = Math.round(m.price * 100) / 100;
    m.history.push({ day: state.player.day, price: m.price });
    if (m.history.length > 20) m.history.shift();
  }

  // 比特币行情
  if (inv.btcPrice > 0) {
    const fg = inv.btcFearGreed || 50;
    const fgNoise = (Math.random() - 0.5) * 10;
    inv.btcFearGreed = Math.max(5, Math.min(95, fg + fgNoise));
    const btcVol = 0.04;
    const btcNoise = (Math.random() - 0.5) * 2 * btcVol;
    const fgEffect = ((inv.btcFearGreed - 50) / 50) * 0.02;
    inv.btcPrice = Math.max(1000, inv.btcPrice * (1 + btcNoise + fgEffect));
    inv.btcPrice = Math.round(inv.btcPrice);
    // 减半周期
    if (state.player.day - inv.btcHalvingDay > 1460) {
      inv.btcHalvingDay = state.player.day;
      inv.btcFearGreed = Math.min(95, inv.btcFearGreed + 15);
      StateManager.addMessage("🪙 比特币减半事件！市场情绪高涨！", "event");
    }
    // 极端行情2%
    if (Math.random() < 0.02) {
      const shock = Math.random() < 0.5 ? 1.25 : 0.7;
      inv.btcPrice = Math.round(inv.btcPrice * shock);
      inv.btcFearGreed = Math.max(5, Math.min(95, inv.btcFearGreed + (shock > 1 ? 20 : -20)));
    }
    if (inv.btcHistory.length > 20) inv.btcHistory.shift();
    inv.btcHistory.push({ day: state.player.day, price: inv.btcPrice });
  }

  // 房产增值+收租（每30天）
  for (const p of inv.properties || []) {
    p.currentPrice = Math.round((p.currentPrice || p.buyPrice) * (1 + p.appreciation + (Math.random() - 0.5) * 0.002));
    if (state.player.day % 30 === 0) {
      state.resources.cash += p.rent || 0;
    }
  }

  // 汽车折旧+保养（每30天）
  for (const c of inv.cars || []) {
    c.currentPrice = Math.round((c.currentPrice || c.buyPrice) * (1 - c.depreciation));
    if (state.player.day % 30 === 0 && state.resources.cash >= c.maintenance) {
      state.resources.cash -= c.maintenance;
    }
  }
}

// ====== 买卖接口 ======
function buyInvStock(symbol, shares) {
  const state = StateManager.getState();
  const inv = state.investment;
  const m = inv.stockMarket[symbol];
  if (!m) return;
  const cost = Math.round(m.price * shares * 100) / 100;
  if (state.resources.cash < cost) { StateManager.addMessage("⚠️ 现金不足", "danger"); return; }
  state.resources.cash -= cost;
  const h = inv.stockHoldings.find(s => s.symbol === symbol);
  if (h) { h.shares += shares; h.avgPrice = Math.round(((h.avgPrice * (h.shares - shares) + cost) / h.shares) * 100) / 100; }
  else inv.stockHoldings.push({ symbol, shares, avgPrice: m.price });
  StateManager.addMessage(`📈 买入 ${symbol} ×${shares}股 @¥${m.price}`, "success");
}

function sellInvStock(symbol, shares) {
  const state = StateManager.getState();
  const inv = state.investment;
  const h = inv.stockHoldings.find(s => s.symbol === symbol);
  if (!h || h.shares < shares) { StateManager.addMessage("⚠️ 持仓不足", "danger"); return; }
  const m = inv.stockMarket[symbol];
  const revenue = Math.round(m.price * shares * 100) / 100;
  state.resources.cash += revenue;
  h.shares -= shares;
  if (h.shares <= 0) inv.stockHoldings = inv.stockHoldings.filter(s => s.symbol !== symbol);
  const profit = Math.round(revenue - h.avgPrice * shares);
  StateManager.addMessage(`💰 卖出 ${symbol} ×${shares}股, ¥${revenue}。${profit >= 0 ? "📈" : "📉"} ¥${Math.abs(profit)}`, profit >= 0 ? "success" : "warning");
}

function buyBtc(amount) {
  const state = StateManager.getState();
  const inv = state.investment;
  const cost = Math.round(inv.btcPrice * amount * 100) / 100;
  if (state.resources.cash < cost) { StateManager.addMessage("⚠️ 现金不足", "danger"); return; }
  state.resources.cash -= cost;
  inv.btcHoldings = Math.round((inv.btcHoldings + amount) * 10000) / 10000;
  StateManager.addMessage(`🪙 买入 ${amount} BTC @¥${inv.btcPrice.toLocaleString()}`, "success");
}

function sellBtc(amount) {
  const state = StateManager.getState();
  const inv = state.investment;
  if (inv.btcHoldings < amount) { StateManager.addMessage("⚠️ 持仓不足", "danger"); return; }
  const revenue = Math.round(inv.btcPrice * amount * 100) / 100;
  state.resources.cash += revenue;
  inv.btcHoldings = Math.round((inv.btcHoldings - amount) * 10000) / 10000;
  StateManager.addMessage(`💰 卖出 ${amount} BTC, ¥${revenue.toLocaleString()}`, "success");
}

function buyProperty(propId) {
  const state = StateManager.getState();
  const inv = state.investment;
  const prop = PROPERTIES.find(p => p.id === propId);
  if (!prop) return;
  if (state.resources.cash < prop.price) { StateManager.addMessage("⚠️ 现金不足", "danger"); return; }
  if (inv.properties.find(p => p.id === propId)) { StateManager.addMessage("⚠️ 已拥有该房产", "warning"); return; }
  state.resources.cash -= prop.price;
  inv.properties.push({ ...prop, buyPrice: prop.price, currentPrice: prop.price, buyDay: state.player.day });
  StateManager.addMessage(`🏠 购入${prop.name}，¥${prop.price.toLocaleString()}`, "success");
}

function sellProperty(propId) {
  const state = StateManager.getState();
  const inv = state.investment;
  const idx = inv.properties.findIndex(p => p.id === propId);
  if (idx < 0) return;
  const prop = inv.properties[idx];
  const tax = Math.round(prop.currentPrice * 0.05);
  const net = prop.currentPrice - tax;
  state.resources.cash += net;
  inv.properties.splice(idx, 1);
  StateManager.addMessage(`🏠 出售${prop.name}，到手 ¥${net.toLocaleString()}（税¥${tax}）`, "success");
}

function buyCar(carId) {
  const state = StateManager.getState();
  const inv = state.investment;
  const car = CAR_TYPES.find(c => c.id === carId);
  if (!car) return;
  if (state.resources.cash < car.price) { StateManager.addMessage("⚠️ 现金不足", "danger"); return; }
  if (inv.cars.find(c => c.id === carId)) { StateManager.addMessage("⚠️ 已拥有该车", "warning"); return; }
  state.resources.cash -= car.price;
  inv.cars.push({ ...car, buyPrice: car.price, currentPrice: car.price, buyDay: state.player.day });
  state.player.maxActionPoints = (state.player.maxActionPoints || 100) + car.travelBonus;
  state.player.actionPoints = Math.min(state.player.maxActionPoints, state.player.actionPoints + car.travelBonus);
  StateManager.addMessage(`🚗 购入${car.name}，行动力上限+${car.travelBonus}！`, "success");
}

// ====== 投资Tab渲染 ======
function renderInvestmentTab(state, parent) {
  const inv = state.investment;
  if (!inv) { parent.innerHTML = '<p>投资系统加载中...</p>'; return; }

  // 初始化
  if (Object.keys(inv.stockMarket).length === 0) initInvestment(state);
  if (typeof bootstrapInvestmentHistory === "function") bootstrapInvestmentHistory(state);

  const container = document.createElement("div");
  container.style.cssText = "display:flex;flex-direction:column;gap:16px;";

  // 总资产概览
  const stockVal = inv.stockHoldings.reduce((s, h) => s + (inv.stockMarket[h.symbol]?.price || 0) * h.shares, 0);
  const btcVal = inv.btcPrice * inv.btcHoldings;
  const propVal = (inv.properties || []).reduce((s, p) => s + (p.currentPrice || p.buyPrice), 0);
  const carVal = (inv.cars || []).reduce((s, c) => s + (c.currentPrice || c.buyPrice), 0);
  const totalInv = stockVal + btcVal + propVal + carVal;

  container.innerHTML = `
    <div style="display:flex;gap:12px;flex-wrap:wrap;">
      <div class="action-card" style="flex:1;min-width:120px;text-align:center;">
        <div style="font-size:10px;color:var(--text-muted);">📈 股票市值</div>
        <div style="font-size:16px;font-weight:600;">¥${stockVal.toLocaleString()}</div>
      </div>
      <div class="action-card" style="flex:1;min-width:120px;text-align:center;">
        <div style="font-size:10px;color:var(--text-muted);">🪙 比特币</div>
        <div style="font-size:16px;font-weight:600;">¥${btcVal.toLocaleString()}</div>
      </div>
      <div class="action-card" style="flex:1;min-width:120px;text-align:center;">
        <div style="font-size:10px;color:var(--text-muted);">🏠 房产</div>
        <div style="font-size:16px;font-weight:600;">¥${propVal.toLocaleString()}</div>
      </div>
      <div class="action-card" style="flex:1;min-width:120px;text-align:center;">
        <div style="font-size:10px;color:var(--text-muted);">🚗 汽车</div>
        <div style="font-size:16px;font-weight:600;">¥${carVal.toLocaleString()}</div>
      </div>
    </div>
    <div style="text-align:center;font-size:14px;color:var(--accent);">
      💰 投资总资产: <strong>¥${totalInv.toLocaleString()}</strong>
    </div>
    <div style="display:flex;gap:4px;">
      <button class="btn btn-sm sub-tab-btn active" data-sub="stocks">📈 股票</button>
      <button class="btn btn-sm sub-tab-btn" data-sub="btc">🪙 比特币</button>
      <button class="btn btn-sm sub-tab-btn" data-sub="re">🏠 房产</button>
      <button class="btn btn-sm sub-tab-btn" data-sub="car">🚗 汽车</button>
    </div>
    <div id="inv-sub-content"></div>
  `;
  parent.appendChild(container);

  const renderSub = (sub) => {
    const subDiv = document.getElementById("inv-sub-content");
    if (!subDiv) return;
    if (sub === "stocks") renderStockSub(state, subDiv);
    else if (sub === "btc") renderBtcSub(state, subDiv);
    else if (sub === "re") renderPropertySub(state, subDiv);
    else if (sub === "car") renderCarSub(state, subDiv);
  };

  setTimeout(() => {
    renderSub("stocks");
    parent.querySelectorAll(".sub-tab-btn").forEach(btn => {
      btn.addEventListener("click", () => {
        parent.querySelectorAll(".sub-tab-btn").forEach(b => b.classList.remove("active"));
        btn.classList.add("active");
        renderSub(btn.dataset.sub);
      });
    });
  }, 0);
}

function renderStockSub(state, parent) {
  const inv = state.investment;
  let html = '<div class="action-cards" style="grid-template-columns:repeat(auto-fill,minmax(260px,1fr));">';
  for (const s of INV_STOCKS) {
    const m = inv.stockMarket[s.symbol];
    if (!m) continue;
    const h = inv.stockHoldings.find(h => h.symbol === s.symbol);
    const prev = m.history.length >= 2 ? m.history[m.history.length - 2].price : m.price;
    const chg = m.price - prev;
    const color = chg >= 0 ? "var(--success)" : "var(--danger)";
    html += `<div class="action-card" style="border-left:3px solid ${color};">
      <div style="display:flex;justify-content:space-between;">
        <strong>${s.symbol}</strong><span style="color:${color};">¥${m.price.toFixed(2)}</span>
      </div>
      <div style="font-size:10px;color:var(--text-muted);">${s.industry} | 波动${(s.volatility*100).toFixed(0)}%</div>
      ${h ? `<div style="font-size:10px;margin:4px 0;">持仓: ${h.shares}股 | 均价 ¥${h.avgPrice.toFixed(2)} | 盈亏: <span style="color:${color}">¥${Math.round((m.price - h.avgPrice) * h.shares)}</span></div>` : ""}
      <div style="display:flex;gap:4px;margin-top:6px;">
        <button class="btn btn-sm btn-success inv-buy-stock" data-sym="${s.symbol}" data-qty="10">买10</button>
        <button class="btn btn-sm btn-success inv-buy-stock" data-sym="${s.symbol}" data-qty="100">买100</button>
        <button class="btn btn-sm btn-danger inv-sell-stock" data-sym="${s.symbol}" data-qty="10">卖10</button>
        <button class="btn btn-sm btn-danger inv-sell-stock" data-sym="${s.symbol}" data-qty="${h ? h.shares : 0}">全卖</button>
      </div>
    </div>`;
  }
  html += '</div>';
  parent.innerHTML = html;
  setTimeout(() => {
    parent.querySelectorAll(".inv-buy-stock").forEach(b => b.onclick = () => { buyInvStock(b.dataset.sym, parseInt(b.dataset.qty)); renderInvestmentTab(state, document.getElementById("content-area")); });
    parent.querySelectorAll(".inv-sell-stock").forEach(b => b.onclick = () => { sellInvStock(b.dataset.sym, parseInt(b.dataset.qty)); renderInvestmentTab(state, document.getElementById("content-area")); });
  }, 0);
}

function renderBtcSub(state, parent) {
  const inv = state.investment;
  const fg = inv.btcFearGreed || 50;
  const fgColor = fg > 60 ? "var(--success)" : fg < 40 ? "var(--danger)" : "var(--warning)";
  parent.innerHTML = `
    <div class="action-card" style="max-width:400px;">
      <h3>🪙 比特币</h3>
      <div style="font-size:24px;font-weight:700;color:var(--accent);">¥${inv.btcPrice.toLocaleString()}</div>
      <div style="margin:8px 0;">恐慌贪婪指数: <span style="color:${fgColor};font-weight:600;">${fg} (${fg > 60 ? "贪婪" : fg < 40 ? "恐慌" : "中性"})</span></div>
      <div>持仓: <strong>${inv.btcHoldings}</strong> BTC</div>
      <div style="margin:4px 0;">市值: ¥${Math.round(inv.btcPrice * inv.btcHoldings).toLocaleString()}</div>
      <div style="display:flex;gap:4px;margin-top:8px;">
        <button class="btn btn-success btn-sm" onclick="buyBtc(0.01);renderInvestmentTab(StateManager.getState(), document.getElementById('content-area'));">买0.01</button>
        <button class="btn btn-success btn-sm" onclick="buyBtc(0.1);renderInvestmentTab(StateManager.getState(), document.getElementById('content-area'));">买0.1</button>
        <button class="btn btn-danger btn-sm" onclick="sellBtc(0.01);renderInvestmentTab(StateManager.getState(), document.getElementById('content-area'));">卖0.01</button>
        <button class="btn btn-danger btn-sm" onclick="sellBtc(inv.btcHoldings);renderInvestmentTab(StateManager.getState(), document.getElementById('content-area'));">全卖</button>
      </div>
    </div>`;
}

function renderPropertySub(state, parent) {
  const inv = state.investment;
  let html = '<div class="action-cards" style="grid-template-columns:repeat(auto-fill,minmax(240px,1fr));">';
  for (const p of PROPERTIES) {
    const owned = inv.properties.find(po => po.id === p.id);
    html += `<div class="action-card">
      <strong>${p.name}</strong>
      <div style="font-size:10px;color:var(--text-muted);">${p.type} | ¥${p.price.toLocaleString()}</div>
      <div style="font-size:10px;">月租 ¥${p.rent.toLocaleString()} | ${p.desc}</div>
      ${owned ? `<div style="color:var(--success);margin-top:4px;">✅ 已拥有 | 当前值 ¥${owned.currentPrice.toLocaleString()}</div>
        <button class="btn btn-sm btn-danger" onclick="sellProperty('${p.id}');renderInvestmentTab(StateManager.getState(), document.getElementById('content-area'));">出售 (-5%税)</button>` :
        `<button class="btn btn-sm btn-success" onclick="buyProperty('${p.id}');renderInvestmentTab(StateManager.getState(), document.getElementById('content-area'));">购入 ¥${p.price.toLocaleString()}</button>`}
    </div>`;
  }
  html += '</div>';
  parent.innerHTML = html;
}

function renderCarSub(state, parent) {
  const inv = state.investment;
  let html = '<div class="action-cards" style="grid-template-columns:repeat(auto-fill,minmax(240px,1fr));">';
  for (const c of CAR_TYPES) {
    const owned = inv.cars.find(co => co.id === c.id);
    html += `<div class="action-card">
      <strong>${c.name}</strong>
      <div style="font-size:10px;color:var(--text-muted);">¥${c.price.toLocaleString()} | 月保养 ¥${c.maintenance}</div>
      <div style="font-size:10px;">行动力上限+${c.travelBonus} | ${c.desc}</div>
      ${owned ? `<div style="color:var(--success);margin-top:4px;">✅ 已拥有 | 当前值 ¥${owned.currentPrice.toLocaleString()}</div>` :
        `<button class="btn btn-sm btn-success" onclick="buyCar('${c.id}');renderInvestmentTab(StateManager.getState(), document.getElementById('content-area'));">购入 ¥${c.price.toLocaleString()}</button>`}
    </div>`;
  }
  html += '</div>';
  parent.innerHTML = html;
}

