code = '''
function buyInvStock(symbol, shares) {
  const state = StateManager.getState(); const inv = state.investment; const m = inv.stockMarket[symbol];
  if (!m) return;
  const cost = Math.round(m.price * shares * 100) / 100;
  if (state.resources.cash < cost) { StateManager.addMessage(\"现金不足\", \"danger\"); return; }
  state.resources.cash -= cost;
  const h = inv.stockHoldings.find(s => s.symbol === symbol);
  if (h) { const total = h.shares + shares; h.avgPrice = Math.round(((h.avgPrice * h.shares + cost) / total) * 100) / 100; h.shares = total; }
  else inv.stockHoldings.push({ symbol, shares, avgPrice: m.price });
  StateManager.addMessage(\"买入 \" + symbol + \" \" + shares + \"股\", \"success\");
}

function sellInvStock(symbol, shares) {
  const state = StateManager.getState(); const inv = state.investment;
  const h = inv.stockHoldings.find(s => s.symbol === symbol);
  if (!h || h.shares < shares) { StateManager.addMessage(\"持仓不足\", \"danger\"); return; }
  const m = inv.stockMarket[symbol]; const revenue = Math.round(m.price * shares * 100) / 100;
  state.resources.cash += revenue; h.shares -= shares;
  if (h.shares <= 0) inv.stockHoldings = inv.stockHoldings.filter(s => s.symbol !== symbol);
  StateManager.addMessage(\"卖出 \" + symbol + \" \" + shares + \"股\", \"success\");
}

function buyBtc(amount) {
  const state = StateManager.getState(); const inv = state.investment;
  const cost = Math.round(inv.btcPrice * amount * 100) / 100;
  if (state.resources.cash < cost) { StateManager.addMessage(\"现金不足\", \"danger\"); return; }
  state.resources.cash -= cost; inv.btcHoldings = Math.round((inv.btcHoldings + amount) * 10000) / 10000;
  StateManager.addMessage(\"买入 \" + amount + \" BTC\", \"success\");
}

function sellBtc(amount) {
  const state = StateManager.getState(); const inv = state.investment;
  if (inv.btcHoldings < amount) { StateManager.addMessage(\"持仓不足\", \"danger\"); return; }
  state.resources.cash += Math.round(inv.btcPrice * amount * 100) / 100;
  inv.btcHoldings = Math.round((inv.btcHoldings - amount) * 10000) / 10000;
  StateManager.addMessage(\"卖出 \" + amount + \" BTC\", \"success\");
}

function buyProperty(propId) {
  const state = StateManager.getState(); const inv = state.investment;
  const prop = PROPERTIES.find(p => p.id === propId); if (!prop) return;
  if (state.resources.cash < prop.price) { StateManager.addMessage(\"现金不足\", \"danger\"); return; }
  state.resources.cash -= prop.price;
  inv.properties.push({ ...prop, buyPrice: prop.price, currentPrice: prop.price, buyDay: state.player.day });
  StateManager.addMessage(\"购入\" + prop.name, \"success\");
}

function sellProperty(propId) {
  const state = StateManager.getState(); const inv = state.investment;
  const idx = inv.properties.findIndex(p => p.id === propId); if (idx < 0) return;
  const prop = inv.properties[idx]; const net = prop.currentPrice - Math.round(prop.currentPrice * 0.05);
  state.resources.cash += net; inv.properties.splice(idx, 1);
  StateManager.addMessage(\"出售\" + prop.name + \" 到手\" + net, \"success\");
}

function buyCar(carId) {
  const state = StateManager.getState(); const inv = state.investment;
  const car = CAR_TYPES.find(c => c.id === carId); if (!car) return;
  if (state.resources.cash < car.price) { StateManager.addMessage(\"现金不足\", \"danger\"); return; }
  state.resources.cash -= car.price;
  inv.cars.push({ ...car, buyPrice: car.price, currentPrice: car.price, buyDay: state.player.day });
  state.player.maxActionPoints = (state.player.maxActionPoints || 100) + car.travelBonus;
  state.player.actionPoints = Math.min(state.player.maxActionPoints, state.player.actionPoints + car.travelBonus);
  StateManager.addMessage(\"购入\" + car.name + \" 行动力上限+\" + car.travelBonus, \"success\");
}
