rcode = r"""
function renderInvestmentTab(state, parent) {
  const inv = state.investment; if (!inv) { parent.innerHTML = '<p>投资系统加载中...</p>'; return; }
  if (Object.keys(inv.stockMarket).length === 0 && typeof initInvestment === 'function') initInvestment(state);

  const stockVal = inv.stockHoldings.reduce((s, h) => s + (inv.stockMarket[h.symbol]?.price || 0) * h.shares, 0);
  const btcVal = inv.btcPrice * inv.btcHoldings;
  const propVal = (inv.properties || []).reduce((s, p) => s + (p.currentPrice || p.buyPrice), 0);
  const carVal = (inv.cars || []).reduce((s, c) => s + (c.currentPrice || c.buyPrice), 0);
  const totalInv = stockVal + btcVal + propVal + carVal;

  parent.innerHTML = '';
  const cont = document.createElement('div');
  cont.innerHTML = '<h3>投资中心 <span style="font-size:12px;color:var(--accent);">总资产 ' + totalInv.toLocaleString() + '</span></h3>' +
    '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;">' +
    '<div class="action-card" style="flex:1;min-width:100px;text-align:center;padding:8px;"><div style="font-size:10px;color:var(--text-muted);">股票</div><strong>' + stockVal.toLocaleString() + '</strong></div>' +
    '<div class="action-card" style="flex:1;min-width:100px;text-align:center;padding:8px;"><div style="font-size:10px;color:var(--text-muted);">比特币</div><strong>' + btcVal.toLocaleString() + '</strong></div>' +
    '<div class="action-card" style="flex:1;min-width:100px;text-align:center;padding:8px;"><div style="font-size:10px;color:var(--text-muted);">房产</div><strong>' + propVal.toLocaleString() + '</strong></div>' +
    '<div class="action-card" style="flex:1;min-width:100px;text-align:center;padding:8px;"><div style="font-size:10px;color:var(--text-muted);">汽车</div><strong>' + carVal.toLocaleString() + '</strong></div>' +
    '</div>' +
    '<div style="display:flex;gap:4px;margin-bottom:8px;">' +
    '<button class="btn btn-sm sub-tab active" data-stab="stocks">股票</button>' +
    '<button class="btn btn-sm sub-tab" data-stab="btc">比特币</button>' +
    '<button class="btn btn-sm sub-tab" data-stab="re">房产</button>' +
    '<button class="btn btn-sm sub-tab" data-stab="car">汽车</button>' +
    '</div><div id="inv-sub-area"></div>';
  parent.appendChild(cont);

  const renderSub = function(stab) {
    const area = document.getElementById('inv-sub-area'); if (!area) return;
    area.innerHTML = '';
    if (stab === 'stocks') {
      const grid = document.createElement('div'); grid.className = 'action-cards'; grid.style.gridTemplateColumns = 'repeat(auto-fill,minmax(220px,1fr))';
      for (const s of INV_STOCKS) {
        const m = inv.stockMarket[s.symbol]; if (!m) continue;
        const h = inv.stockHoldings.find(function(h) { return h.symbol === s.symbol; });
        const chg = m.history.length >= 2 ? m.price - m.history[m.history.length - 2].price : 0;
        const clr = chg >= 0 ? 'var(--success)' : 'var(--danger)';
        const card = document.createElement('div'); card.className = 'action-card'; card.style.borderLeft = '3px solid ' + clr;
        card.innerHTML = '<div style="display:flex;justify-content:space-between;"><strong>' + s.symbol + ' ' + s.name + '</strong><span style="color:' + clr + '">' + m.price.toFixed(2) + '</span></div>' +
          '<div style="font-size:10px;color:var(--text-muted);">' + s.industry + ' | ' + s.desc + '</div>' +
          (h ? '<div style="font-size:10px;margin:4px 0;">持仓' + h.shares + '股 均价' + h.avgPrice.toFixed(2) + ' 盈亏<span style="color:' + clr + '">' + Math.round((m.price - h.avgPrice) * h.shares) + '</span></div>' : '') +
          '<div style="display:flex;gap:3px;margin-top:4px;">' +
          '<button class="btn btn-sm btn-success ibuy" data-s="' + s.symbol + '" data-q="10">买10</button>' +
          '<button class="btn btn-sm btn-success ibuy" data-s="' + s.symbol + '" data-q="100">买100</button>' +
          '<button class="btn btn-sm btn-danger isell" data-s="' + s.symbol + '" data-q="10">卖10</button>' +
          '<button class="btn btn-sm btn-danger isell" data-s="' + s.symbol + '" data-q="' + (h ? h.shares : 0) + '">全卖</button></div>';
        grid.appendChild(card);
      }
      area.appendChild(grid);
      setTimeout(function() {
        area.querySelectorAll('.ibuy').forEach(function(b) { b.onclick = function() { buyInvStock(b.dataset.s, parseInt(b.dataset.q)); renderInvestmentTab(state, parent); }; });
        area.querySelectorAll('.isell').forEach(function(b) { b.onclick = function() { sellInvStock(b.dataset.s, parseInt(b.dataset.q)); renderInvestmentTab(state, parent); }; });
      }, 0);
    }
  };

  setTimeout(function() {
    renderSub('stocks');
    cont.querySelectorAll('.sub-tab').forEach(function(btn) {
      btn.addEventListener('click', function() {
        cont.querySelectorAll('.sub-tab').forEach(function(b) { b.classList.remove('active'); });
        btn.classList.add('active');
        renderSub(btn.dataset.stab);
      });
    });
  }, 0);
}
"""
